{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "작은 카페의 강아지 동반 가능 안내판 설치비를 시나 구청에서 지원하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제7조의4 제1항에 따르면, 시장과 구청장은 다중이용시설의 관리책임이 있는 자가 반려동물 출입가능 여부 등을 표시하는 경우 표시장비 등의 설치비용을 예산의 범위에서 지원할 수 있습니다. 작은 카페가 불특정다수인이 이용하는 다중이용시설에 해당하고, 강아지 동반 가능 안내판을 설치한다면 그 설치비용을 지원받을 수 있는 대상이 될 수 있습니다. 다만 지원 여부와 지원 금액은 예산 범위 및 제2항에 따라 정하는 지원대상 다중이용시설의 범위에 따라 결정됩니다.",
          "b_ids": "동물보호:제7조의4제1항, 동물보호:제7조의4제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
